WITH doc_key AS ( SELECT id AS k, id AS doc_id FROM document UNION SELECT number AS k, id AS doc_id FROM document WHERE number IS NOT NULL ), docn AS ( SELECT id AS doc_id, number, replace(replace(replace(replace(replace(replace(lower(trim(target_release)), 'release', ''), 'rel', ''), 'r', ''), '-', ''), ' ', ''), '.', '') AS trel FROM document ), pack AS ( SELECT id AS pack_id, COALESCE(pack_number, id) AS pack_number, tsg_meeting, CASE WHEN tsg_number IS NOT NULL THEN tsg_number WHEN instr(tsg_meeting, '#') > 0 THEN CAST(substr(tsg_meeting, instr(tsg_meeting, '#') + 1) AS INTEGER) END AS tsg_num FROM cr_pack ), pack_key AS ( SELECT pack_id AS k, pack_id FROM pack UNION SELECT pack_number AS k, pack_id FROM pack ), mem AS ( SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member ), docpack AS ( SELECT DISTINCT dk.doc_id, p.pack_id, p.pack_number, p.tsg_meeting, p.tsg_num FROM mem JOIN doc_key dk ON dk.k = mem.cr JOIN pack_key pk ON pk.k = mem.pack_id JOIN pack p ON p.pack_id = pk.pack_id ), mods AS ( SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by ), secn AS ( SELECT id AS section_id, spec, clause, replace(replace(replace(replace(replace(replace(lower(trim(release)), 'release', ''), 'rel', ''), 'r', ''), '-', ''), ' ', ''), '.', '') AS rel FROM section ), crclause AS ( SELECT DISTINCT dk.doc_id, s.spec, s.clause, s.rel FROM mods JOIN doc_key dk ON dk.k = mods.cr JOIN secn s ON s.section_id = mods.section_id JOIN docn d ON d.doc_id = dk.doc_id WHERE s.rel = d.trel AND s.rel <> '' ), vdisp AS ( SELECT DISTINCT dk.doc_id, di.code, COALESCE(m.label, m.id) AS wg_meeting FROM disposition di JOIN doc_key dk ON dk.k = di.target JOIN resolution r ON r.id = di.resolution_id JOIN meeting m ON m.id = r.meeting_id WHERE replace(replace(lower(trim(di.evidence_status)), '_', '-'), ' ', '-') IN ('source-verified', 'verified', 'sourceverified', 'verified-source') AND replace(replace(lower(trim(di.scope)), '_', ' '), '-', ' ') IN ('whole document', 'document', 'whole', 'full document', 'full', 'entire document', 'whole doc', 'doc', 'whole tdoc', 'tdoc', 'full tdoc', 'entire', 'all') AND upper(replace(replace(replace(trim(m.wg), ' ', ''), '_', ''), '-', '')) IN ('RAN4', 'R4', 'RANWG4', 'WG4', 'TSGRANWG4') ) , x AS ( SELECT doc_id FROM docn WHERE number = '{ANCHOR}' OR doc_id = '{ANCHOR}' ), xcl AS ( SELECT DISTINCT cc.spec, cc.clause, cc.rel FROM crclause cc JOIN x ON x.doc_id = cc.doc_id ) SELECT DISTINCT xc.clause AS clause, COALESCE(d2.number, d2.doc_id) AS document, v.code AS disposition, v.wg_meeting AS wg_meeting, dp.pack_number AS cr_pack FROM xcl xc JOIN crclause c2 ON c2.spec = xc.spec AND c2.clause = xc.clause AND c2.rel = xc.rel JOIN docn d2 ON d2.doc_id = c2.doc_id JOIN vdisp v ON v.doc_id = c2.doc_id JOIN docpack dp ON dp.doc_id = c2.doc_id WHERE c2.doc_id NOT IN (SELECT doc_id FROM x) AND COALESCE(d2.number, '') <> '{ANCHOR}'
